use std::fs;
use std::io;
use std::num::ParseIntError;

// ❌ OLD: Manual nested matching. Every fallible call nests another
// level, the happy path is buried, and each error needs an explicit
// conversion (e.into()). Adding a third fallible step triples the
// nesting.
fn read_number(path: &str) -> Result<i32, Box<dyn std::error::Error>> {
    match fs::read_to_string(path) {
        Ok(s) => match s.trim().parse::<i32>() {
            Ok(n) => Ok(n),
            Err(e) => Err(e.into()), // ❌ OLD: manual conversion
        },
        Err(e) => Err(e.into()), // ❌ OLD: manual conversion
    }
}

