use std::fs;

// ✅ NEW: The ? operator flattens the flow. Each ? desugars to:
//   match expr { Ok(v) => v, Err(e) => return Err(From::from(e)) }
// so io::Error and ParseIntError are auto-converted into
// Box<dyn std::error::Error> via the blanket From impl.
fn read_number(path: &str) -> Result<i32, Box<dyn std::error::Error>> {
    let s = fs::read_to_string(path)?; // ✅ NEW: auto-converts io::Error
    Ok(s.trim().parse::<i32>()?) // ✅ NEW: auto-converts ParseIntError
}

